package com.hbm.network.cargo.request;
import net.minecraft.core.BlockPos;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.world.entity.player.*;
import net.minecraft.world.inventory.*;
import net.minecraft.world.item.ItemStack;
public final class CargoRequestMenu extends AbstractContainerMenu {
 public final CargoRequestContent.Kind kind;public final RequestContainerEntity tile;
 public CargoRequestMenu(int id,Inventory inv,RegistryFriendlyByteBuf buf,CargoRequestContent.Kind kind){this(id,inv,resolve(inv,buf.readBlockPos(),kind),kind);}private static RequestContainerEntity resolve(Inventory inv,BlockPos pos,CargoRequestContent.Kind kind){if(inv.player.level().getBlockEntity(pos) instanceof RequestContainerEntity tile)return tile;var state=CargoRequestContent.BLOCKS_BY_KIND.get(kind).get().defaultBlockState();return switch(kind){case DOCK->new DroneDockEntity(pos,state);case PROVIDER->new DroneProviderEntity(pos,state);case REQUESTER->new DroneRequesterEntity(pos,state);};}
 public CargoRequestMenu(int id,Inventory inv,RequestContainerEntity tile,CargoRequestContent.Kind kind){super(CargoRequestContent.MENUS_BY_KIND.get(kind).get(),id);this.kind=kind;this.tile=tile;if(kind==CargoRequestContent.Kind.REQUESTER){for(int y=0;y<3;y++)for(int x=0;x<3;x++)addSlot(new Slot(tile,x+y*3,98+x*18,17+y*18){@Override public boolean mayPickup(Player p){return false;}@Override public int getMaxStackSize(){return 1;}@Override public void set(ItemStack stack){super.set(stack.isEmpty()?ItemStack.EMPTY:stack.copyWithCount(1));}});for(int y=0;y<3;y++)for(int x=0;x<3;x++)addSlot(new Slot(tile,x+y*3+9,26+x*18,17+y*18));}else for(int y=0;y<3;y++)for(int x=0;x<3;x++)addSlot(new Slot(tile,x+y*3,62+x*18,17+y*18));for(int y=0;y<3;y++)for(int x=0;x<9;x++)addSlot(new Slot(inv,x+y*9+9,8+x*18,103+y*18){@Override public int getMaxStackSize(){return Math.max(container.getMaxStackSize(),getItem().getCount());}});for(int x=0;x<9;x++)addSlot(new Slot(inv,x,8+x*18,161){@Override public int getMaxStackSize(){return Math.max(container.getMaxStackSize(),getItem().getCount());}});}
 @Override public void clicked(int index,int button,ClickType type,Player player){if(kind!=CargoRequestContent.Kind.REQUESTER||index<0||index>=9){super.clicked(index,button,type,player);return;}var requester=(DroneRequesterEntity)tile;var slot=getSlot(index);if(button==1&&type==ClickType.PICKUP&&slot.hasItem()){if(!player.level().isClientSide)requester.nextMode(index);}else{slot.set(getCarried());if(!player.level().isClientSide)requester.matcher.initPatternStandard(slot.getItem(),index);}requester.setChanged();broadcastChanges();}
 @Override public ItemStack quickMoveStack(Player player,int index){if(index<0||index>=slots.size())return ItemStack.EMPTY;var slot=getSlot(index);if(!slot.hasItem())return ItemStack.EMPTY;var stack=slot.getItem();var copy=stack.copy();int count=tile.getContainerSize();if(kind==CargoRequestContent.Kind.REQUESTER&&index<9)return ItemStack.EMPTY;if(index<count){if(!moveItemStackTo(stack,count,slots.size(),true))return ItemStack.EMPTY;}else if(!moveItemStackTo(stack,kind==CargoRequestContent.Kind.REQUESTER?9:0,count,false))return ItemStack.EMPTY;if(stack.isEmpty())slot.setByPlayer(ItemStack.EMPTY);else slot.setChanged();slot.onTake(player,stack);return copy;}
 @Override public boolean stillValid(Player player){return tile.stillValid(player);}
}
